"use client";

import { motion, AnimatePresence } from "motion/react";
import type { SpringOptions } from "motion/react";
import { useState, useEffect, useRef } from "react";
import { Plus, Mic, ArrowUp } from "lucide-react";

// Self-contained spring presets
export const CHAT_SPRING_PRESETS = {
  gentle: { stiffness: 200, damping: 25, mass: 1 } as SpringOptions,
  snappy: { stiffness: 300, damping: 30, mass: 0.8 } as SpringOptions,
};

type ChatBarDemoState = "idle" | "typing" | "holding" | "deleting";

// ============================================
// ChatBar
// ============================================

interface ChatBarProps {
  placeholder?: string;
  onSend?: (message: string) => void;
  demoState?: ChatBarDemoState;
  demoText?: string;
  demoTypingSpeed?: number;
  onDemoComplete?: () => void;
  className?: string;
}

export function ChatBar({
  placeholder = "Ask anything...",
  onSend,
  demoState = "idle",
  demoText = "",
  demoTypingSpeed = 50,
  onDemoComplete,
  className = "",
}: ChatBarProps) {
  const [value, setValue] = useState("");
  const [cursorVisible, setCursorVisible] = useState(true);
  const [demoDisplayText, setDemoDisplayText] = useState("");
  const onDemoCompleteRef = useRef(onDemoComplete);
  const demoRunIdRef = useRef(0);

  useEffect(() => {
    onDemoCompleteRef.current = onDemoComplete;
  }, [onDemoComplete]);

  useEffect(() => {
    const interval = setInterval(() => {
      setCursorVisible((prev) => !prev);
    }, 530);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    demoRunIdRef.current += 1;
    const currentRunId = demoRunIdRef.current;

    if (value !== "") {
      return;
    }

    if (demoState === "idle") {
      setDemoDisplayText("");
      return;
    }

    if (demoState === "holding") {
      setDemoDisplayText(demoText);
      return;
    }

    if (demoState === "deleting") {
      if (!demoText) {
        setDemoDisplayText("");
        return;
      }

      let currentLength = demoText.length;
      let timeoutId: ReturnType<typeof setTimeout> | undefined;

      const deleteNextChar = () => {
        if (demoRunIdRef.current !== currentRunId) {
          return;
        }

        currentLength -= 1;
        setDemoDisplayText(demoText.slice(0, currentLength));

        if (currentLength > 0) {
          timeoutId = setTimeout(deleteNextChar, demoTypingSpeed);
          return;
        }

        onDemoCompleteRef.current?.();
      };

      timeoutId = setTimeout(deleteNextChar, demoTypingSpeed);

      return () => {
        if (timeoutId) {
          clearTimeout(timeoutId);
        }
      };
    }

    if (!demoText) {
      setDemoDisplayText("");
      return;
    }

    let currentIndex = 0;
    let timeoutId: ReturnType<typeof setTimeout> | undefined;
    setDemoDisplayText("");

    const typeNextChar = () => {
      if (demoRunIdRef.current !== currentRunId) {
        return;
      }

      const nextIndex = currentIndex + 1;
      setDemoDisplayText(demoText.slice(0, nextIndex));
      currentIndex = nextIndex;

      if (nextIndex < demoText.length) {
        timeoutId = setTimeout(typeNextChar, demoTypingSpeed);
        return;
      }

      onDemoCompleteRef.current?.();
    };

    timeoutId = setTimeout(typeNextChar, demoTypingSpeed);

    return () => {
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    };
  }, [demoState, demoText, demoTypingSpeed, value]);

  const handleSubmit = () => {
    if (value.trim() && onSend) {
      onSend(value);
      setValue("");
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const isDemoVisible = value === "" && demoState !== "idle";

  return (
    <motion.div
      initial={{ y: 20, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ ...CHAT_SPRING_PRESETS.gentle }}
      className={`bg-white rounded-2xl shadow-lg px-4 py-3 flex items-center gap-3 ${className}`}
    >
      <motion.button
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        className="w-8 h-8 rounded-full bg-zinc-100 flex items-center justify-center text-zinc-600 hover:bg-zinc-200 transition-colors"
      >
        <Plus className="w-4 h-4" />
      </motion.button>

      <div className="flex-1 relative">
        <div className="relative flex items-center">
          <AnimatePresence mode="wait">
            {value === "" && demoState === "idle" && (
              <motion.span
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute text-zinc-400 pointer-events-none text-sm"
              >
                {placeholder}
              </motion.span>
            )}
          </AnimatePresence>

          {isDemoVisible && (
            <div className="pointer-events-none absolute inset-0 flex items-center">
              <div className="inline-flex items-center pr-1">
                <span className="text-zinc-800 text-sm">{demoDisplayText}</span>
                {(demoState === "typing" || demoState === "deleting") && (
                  <motion.span
                    animate={{ opacity: cursorVisible ? 1 : 0 }}
                    transition={{ duration: 0.1 }}
                    className="w-0.5 h-4 bg-zinc-800 ml-0.5 flex-shrink-0"
                  />
                )}
              </div>
            </div>
          )}

          <input
            type="text"
            value={value}
            onChange={(e) => setValue(e.target.value)}
            onKeyDown={handleKeyDown}
            readOnly={isDemoVisible}
            className={`w-full bg-transparent text-sm outline-none placeholder:text-zinc-400 relative z-10 ${
              isDemoVisible ? "text-transparent caret-transparent" : "text-zinc-800"
            }`}
          />
        </div>
      </div>

      <div className="flex items-center gap-2">
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className="w-8 h-8 rounded-full bg-zinc-100 flex items-center justify-center text-zinc-600 hover:bg-zinc-200 transition-colors"
        >
          <Mic className="w-4 h-4" />
        </motion.button>

        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={handleSubmit}
          className="w-8 h-8 rounded-full bg-zinc-900 flex items-center justify-center text-white hover:bg-zinc-800 transition-colors"
        >
          <ArrowUp className="w-4 h-4" />
        </motion.button>
      </div>
    </motion.div>
  );
}

// ============================================
// TypingIndicator
// ============================================

interface TypingIndicatorProps {
  className?: string;
}

export function TypingIndicator({ className = "" }: TypingIndicatorProps) {
  const dotVariants = {
    initial: { y: 0 },
    animate: { y: -4 },
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      transition={{ ...CHAT_SPRING_PRESETS.gentle }}
      className={`flex items-center gap-1.5 ${className}`}
    >
      {[0, 1, 2].map((index) => (
        <motion.div
          key={index}
          variants={dotVariants}
          initial="initial"
          animate="animate"
          transition={{
            duration: 0.4,
            repeat: Infinity,
            repeatType: "reverse",
            delay: index * 0.15,
            ease: "easeInOut",
          }}
          className="w-2 h-2 rounded-full bg-zinc-400"
        />
      ))}
    </motion.div>
  );
}

// ============================================
// UserMessage
// ============================================

interface UserMessageProps {
  message: string;
  className?: string;
}

export function UserMessage({ message, className = "" }: UserMessageProps) {
  return (
    <motion.div
      initial={{ x: 50, opacity: 0, scale: 0.9 }}
      animate={{ x: 0, opacity: 1, scale: 1 }}
      transition={{ ...CHAT_SPRING_PRESETS.snappy }}
      className={`flex justify-end ${className}`}
    >
      <motion.div
        className="bg-zinc-900 text-white px-4 py-2.5 rounded-2xl text-sm font-medium max-w-[80%]"
        whileHover={{ scale: 1.02 }}
      >
        {message}
      </motion.div>
    </motion.div>
  );
}

// ============================================
// AIMessage
// ============================================

interface AIMessageProps {
  message: string;
  subheader?: string;
  isTyping?: boolean;
  typingSpeed?: number;
  onTypingComplete?: () => void;
  className?: string;
}

export function AIMessage({
  message,
  subheader = "AI Assistant",
  isTyping = false,
  typingSpeed = 30,
  onTypingComplete,
  className = "",
}: AIMessageProps) {
  const [displayedText, setDisplayedText] = useState("");
  const [isComplete, setIsComplete] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!isTyping) {
      setDisplayedText(message);
      setIsComplete(true);
      return;
    }

    setDisplayedText("");
    setIsComplete(false);
    let currentIndex = 0;

    const typeNextChar = () => {
      if (currentIndex < message.length) {
        setDisplayedText(message.slice(0, currentIndex + 1));
        currentIndex++;
        timeoutRef.current = setTimeout(typeNextChar, typingSpeed);
      } else {
        setIsComplete(true);
        onTypingComplete?.();
      }
    };

    timeoutRef.current = setTimeout(typeNextChar, typingSpeed);

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [message, isTyping, typingSpeed, onTypingComplete]);

  return (
    <motion.div
      initial={{ x: -20, opacity: 0 }}
      animate={{ x: 0, opacity: 1 }}
      transition={{ ...CHAT_SPRING_PRESETS.gentle }}
      className={`flex flex-col gap-1 ${className}`}
    >
      <span className="text-xs text-zinc-500">{subheader}</span>
      <div className="text-sm text-zinc-800 leading-relaxed">
        {displayedText}
        {isTyping && !isComplete && (
          <motion.span
            animate={{ opacity: [1, 0] }}
            transition={{ duration: 0.5, repeat: Infinity }}
            className="inline-block w-0.5 h-4 bg-zinc-800 ml-0.5 align-middle"
          />
        )}
      </div>
    </motion.div>
  );
}

// ============================================
// ChatContainer
// ============================================

interface ChatContainerProps {
  children: React.ReactNode;
  className?: string;
}

export function ChatContainer({ children, className = "" }: ChatContainerProps) {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className={`flex flex-col gap-4 ${className}`}
    >
      {children}
    </motion.div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence, useInView, useReducedMotion } from "motion/react";
import { RotateCcw } from "lucide-react";
import { ChatBar, TypingIndicator, UserMessage, AIMessage, CHAT_SPRING_PRESETS } from "./ChatComponents";

type ChatDemoPhase = "idle" | "input-typing" | "input-holding" | "user" | "typing" | "response";

const demoConversation = {
  userMessage: "What is the current state of US politics?",
  aiResponse: `The current political landscape in the United States is characterized by significant polarization between the two major parties. Key issues dominating the discourse include economic policy, immigration reform, healthcare access, and climate change legislation.`,
};

interface ChatDemoProps {
  className?: string;
}

export function ChatDemo({ className = "" }: ChatDemoProps) {
  const [phase, setPhase] = useState<ChatDemoPhase>("idle");
  const [hasAutoStarted, setHasAutoStarted] = useState(false);
  const [runCount, setRunCount] = useState(0);

  const containerRef = useRef<HTMLDivElement>(null);
  const activeRunIdRef = useRef(0);
  const pendingChatbarCompletionRef = useRef<{ runId: number; resolve: () => void } | null>(null);
  const isInView = useInView(containerRef, { once: true, margin: "-20%" });
  const prefersReducedMotion = useReducedMotion();

  const wait = (duration: number) =>
    new Promise<void>((resolve) => {
      window.setTimeout(resolve, duration);
    });

  const startDemo = () => {
    setRunCount((current) => current + 1);
  };

  const handleChatbarTypingComplete = () => {
    const pendingCompletion = pendingChatbarCompletionRef.current;

    if (!pendingCompletion || pendingCompletion.runId !== activeRunIdRef.current) {
      return;
    }

    pendingChatbarCompletionRef.current = null;
    pendingCompletion.resolve();
  };

  useEffect(() => {
    if (!isInView || hasAutoStarted) {
      return;
    }

    const frame = window.requestAnimationFrame(() => {
      setHasAutoStarted(true);
      startDemo();
    });

    return () => window.cancelAnimationFrame(frame);
  }, [isInView, hasAutoStarted]);

  useEffect(() => {
    if (runCount === 0) {
      return;
    }

    const runId = runCount;
    activeRunIdRef.current = runId;
    pendingChatbarCompletionRef.current = null;

    if (prefersReducedMotion) {
      const frame = window.requestAnimationFrame(() => {
        if (activeRunIdRef.current === runId) {
          setPhase("response");
        }
      });

      return () => window.cancelAnimationFrame(frame);
    }

    let cancelled = false;
    const isActiveRun = () => !cancelled && activeRunIdRef.current === runId;

    const waitForChatbarCompletion = () =>
      new Promise<void>((resolve) => {
        pendingChatbarCompletionRef.current = { runId, resolve };
      });

    const runSequence = async () => {
      setPhase("idle");
      await wait(300);
      if (!isActiveRun()) return;

      setPhase("input-typing");
      await waitForChatbarCompletion();
      if (!isActiveRun()) return;

      setPhase("input-holding");
      await wait(260);
      if (!isActiveRun()) return;

      setPhase("user");
      await wait(420);
      if (!isActiveRun()) return;

      setPhase("typing");
      await wait(1500);
      if (!isActiveRun()) return;

      setPhase("response");
    };

    runSequence();

    return () => {
      cancelled = true;
      if (pendingChatbarCompletionRef.current?.runId === runId) {
        pendingChatbarCompletionRef.current = null;
      }
    };
  }, [runCount, prefersReducedMotion]);

  return (
    <motion.div
      ref={containerRef}
      initial={{ opacity: 0, scale: 0.98 }}
      animate={isInView ? { opacity: 1, scale: 1 } : {}}
      transition={{ ...CHAT_SPRING_PRESETS.gentle }}
      className={`h-[515px] w-full max-w-2xl bg-zinc-100 rounded-3xl shadow-2xl overflow-hidden flex flex-col relative ${className}`}
    >
      {/* Replay button */}
      <motion.button
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.5 }}
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        onClick={startDemo}
        className="absolute top-4 right-4 z-10 flex items-center gap-2 px-3 py-2 rounded-lg bg-white/90 backdrop-blur-sm text-zinc-600 text-sm font-medium hover:bg-white transition-colors shadow-sm"
      >
        <RotateCcw className="w-4 h-4" />
        Replay
      </motion.button>

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto px-6 py-8 pt-16">
        <div className="space-y-6">
          {/* User Message */}
          <AnimatePresence>
            {(phase === "user" || phase === "typing" || phase === "response") && (
              <UserMessage message={demoConversation.userMessage} />
            )}
          </AnimatePresence>

          {/* Typing Indicator */}
          <AnimatePresence>
            {phase === "typing" && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="pl-4">
                <TypingIndicator />
              </motion.div>
            )}
          </AnimatePresence>

          {/* AI Response */}
          <AnimatePresence>
            {phase === "response" && (
              <AIMessage
                message={demoConversation.aiResponse}
                isTyping={!prefersReducedMotion}
                typingSpeed={10}
              />
            )}
          </AnimatePresence>
        </div>
      </div>

      {/* ChatBar */}
      <div className="px-4 py-4 bg-zinc-100">
        <ChatBar
          demoState={
            phase === "input-typing" ? "typing" : phase === "input-holding" ? "holding" : "idle"
          }
          demoText={demoConversation.userMessage}
          demoTypingSpeed={20}
          onDemoComplete={handleChatbarTypingComplete}
          onSend={(message) => console.log("Sent:", message)}
        />
      </div>
    </motion.div>
  );
}

export default ChatDemo;
